use xiom.io;

use xiom.string;
type Health = {
  current: Int;
  maximum: Int;
  invariant: current >= 0;
  invariant: current <= maximum;
}

fn Health.heal(self, amount: Int) -> Int
  requires: amount >= 0;
{
  let nhp = self.current + amount;
  if nhp > self.maximum { return self.maximum; }
  else { return nhp; }
}

fn main() -> Int {
  let hp = Health { current: 80, maximum: 100 };
  let after = hp.heal(10);
  io.println(string.int_to_str(after));
  return 0;
}
